6	<style>
7	  :root{
8	    --bg:#05060d; --surface-1:#0c0f1c; --border:rgba(255,255,255,0.07); --border-strong:rgba(255,255,255,0.16);
9	    --text:#f4f5fb; --text-muted:#97a1c4; --text-faint:#5b6488;
10	    --brand:#6f47f5; --brand-light:#a48bff; --cyan:#22d3ee; --blue:#3b82f6; --good:#34d399; --warn:#fbbf24; --bad:#f87171;
11	    --font-display:"Sora","Inter",system-ui,sans-serif; --font-body:"Inter",system-ui,sans-serif;
12	  }
13	  *{ box-sizing:border-box; }
14	  body{ margin:0; background:var(--bg); color:var(--text); font-family:var(--font-body); -webkit-font-smoothing:antialiased; padding:32px 24px 64px; }
15	  .wrap{ max-width:1080px; margin:0 auto; }
16	  .tag{ display:flex; align-items:center; gap:8px; font-size:11px; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color:var(--text-faint); margin-bottom:18px; }
17	  .tag .dot{ width:6px; height:6px; border-radius:999px; background:var(--brand-light); box-shadow:0 0 0 3px rgba(164,139,255,0.18); }
18	  .crumb{ font-size:12px; color:var(--text-faint); margin-bottom:14px; }
19	  .crumb span{ color:var(--text-muted); }
20	
21	  /* status header */
22	  .status-header{ background:var(--surface-1); border:1px solid var(--border); border-radius:20px; padding:22px 24px; margin-bottom:16px; display:flex; align-items:center; gap:18px; flex-wrap:wrap; }
23	  .identity-glyph{ width:52px; height:52px; border-radius:14px; background:linear-gradient(145deg,rgba(111,71,245,0.25),rgba(34,211,238,0.1)); border:1px solid rgba(164,139,255,0.3); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
24	  .identity-glyph svg{ width:26px; height:26px; color:var(--brand-light); }
25	  .id-meta h1{ font-family:var(--font-display); font-size:19px; font-weight:700; margin:0 0 3px; }
26	  .id-sub{ font-size:12.5px; color:var(--text-faint); display:flex; align-items:center; gap:8px; }
27	  .status-pill{ display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:700; padding:4px 10px; border-radius:999px; background:rgba(52,211,153,0.14); color:#6ee7b3; }
28	  .status-pill i{ width:6px; height:6px; border-radius:999px; background:#6ee7b3; box-shadow:0 0 6px #6ee7b3; }
29	  .sh-actions{ margin-left:auto; display:flex; gap:8px; }
30	  .act-btn{ display:inline-flex; align-items:center; gap:7px; background:rgba(255,255,255,0.05); border:1px solid var(--border-strong); color:var(--text); font-size:12.5px; font-weight:600; border-radius:10px; padding:9px 14px; cursor:pointer; }
31	  .act-btn svg{ width:14px; height:14px; }
32	  .act-btn.primary{ background:linear-gradient(135deg,var(--brand-light),var(--brand)); color:#0a0714; border:none; }
33	  .act-btn.danger{ background:rgba(248,113,113,0.1); border-color:rgba(248,113,113,0.3); color:#fca5a5; }
34	
35	  .alert-banner{ display:flex; align-items:center; gap:12px; background:rgba(251,191,36,0.1); border:1px solid rgba(251,191,36,0.3); border-radius:16px; padding:13px 18px; margin-bottom:16px; }
36	  .alert-banner svg{ width:18px; height:18px; color:var(--warn); flex-shrink:0; }
37	  .alert-banner .t1{ font-size:13px; font-weight:600; }
38	  .alert-banner .t2{ font-size:11.5px; color:var(--text-muted); }
39	  .alert-banner .act{ margin-left:auto; background:rgba(255,255,255,0.08); border:1px solid var(--border-strong); color:var(--text); font-size:12px; font-weight:600; border-radius:9px; padding:7px 13px; cursor:pointer; white-space:nowrap; }
40	
41	  .tabs{ display:flex; gap:6px; margin-bottom:20px; border-bottom:1px solid var(--border); }
42	  .tab{ display:flex; align-items:center; gap:6px; padding:10px 14px; font-size:13px; font-weight:600; color:var(--text-faint); cursor:pointer; border-bottom:2px solid transparent; margin-bottom:-1px; }
43	  .tab svg{ width:15px; height:15px; }
44	  .tab.active{ color:var(--text); border-bottom-color:var(--brand-light); }
45	  .tabpanel{ display:none; } .tabpanel.active{ display:block; }
46	
47	  .grid2{ display:grid; grid-template-columns:1fr 1fr; gap:16px; } .grid3{ display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
48	  @media (max-width:760px){ .grid2,.grid3{ grid-template-columns:1fr; } }
49	  .panel{ background:var(--surface-1); border:1px solid var(--border); border-radius:18px; padding:20px 22px; margin-bottom:16px; }
50	  .panel-title{ font-family:var(--font-display); font-size:14px; font-weight:700; margin-bottom:14px; }
