67	/**
68	 * Pick the port forward that actually serves a game server's own port, not
69	 * just the first one on the record — a customer can add extra forwards
70	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
71	 * mistaken for the game's real connect port. Falls back to the first forward
72	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
73	 * exact-matching forward yet) still shows *something* rather than nothing.
74	 * Single shared helper so the provisioning-overlay connect string, the header
75	 * connect string, and the custom-domain DNS instructions can never drift from
76	 * each other the way three independent inline copies previously could.
77	 */
78	function gameForwardFor(server: {
79	  portForwards: { guestPort: number; publicPort: number }[];
80	  osTemplate: { family?: string | null };
81	  gamePlan?: { gameFamily?: string | null } | null;
82	}): { guestPort: number; publicPort: number } | undefined {
83	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
84	  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
85	  return server.portForwards.find((f) => f.guestPort === expectedPort) ?? server.portForwards[0];
86	}
