88	function fmtUptime(seconds: number): string {
89	  if (!seconds || seconds <= 0) return "—";
90	  const d = Math.floor(seconds / 86400);
91	  const h = Math.floor((seconds % 86400) / 3600);
92	  const m = Math.floor((seconds % 3600) / 60);
93	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
94	}
