105	export default async function ServerPage({
106	  params,
107	  searchParams,
108	}: {
109	  params: Promise<{ id: string }>;
110	  searchParams: Promise<{ tab?: string; purchase?: string }>;
111	}) {
112	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
113	  const user = await requireUser();
114	  const server = await db.server.findUnique({
115	    where: { id },
116	    include: {
117	      plan: true,
118	      osTemplate: true,
119	      project: true,
120	      portForwards: { orderBy: { publicPort: "asc" } },
121	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
122	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
123	      dedicatedIp: true,
124	      node: true,
125	      // Needed to price a renewal correctly: a game server bills its game plan's
126	      // flat price, not the base VPS plan's term price.
127	      gamePlan: true,
128	    },
129	  });
130	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
131	
132	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
133	  // display value through the decrypt fallback (legacy plaintext rows still work).
134	  const rootPassword = serverRootPassword(server);
135	
136	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
137	    await Promise.all([
138	      db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
139	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
140	      db.osTemplate.findMany({
141	        where: { active: true, category: "PLAIN_OS" },
142	        orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
143	      }),
144	      extraDiskPerGbCents(),
145	      backupPlusMonthlyCents(),
146	      // Live annual discount — feeds the "Renew now" quote below AND the resize
147	      // pickers, so an annual server's renewal/upgrade/downgrade all price against the
148	      // same rate it was sold at.
149	      annualDiscountPct(),
150	      // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
151	      // "Add dedicated IP" card needs the live price to show a customer who does
152	      // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
153	      // of whether this server currently holds any extra disk.
154	      dedicatedIpMonthlyCents(),
155	    ]);
156	
157	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
158	  const owner =
159	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
160	  const renewTaxCtx = await taxContextForUser(owner);
161	
