"use client";

import { useState, type ReactNode } from "react";

// Base tab order. "Manage" (the game control panel) is injected right after
// Overview for game servers only — see `tabs` below.
const BASE_TABS = [
  "Overview",
  "Control panel",
  "Metrics",
  "Console",
  "Files",
  "Snapshots",
  "Backups",
  "Networking",
  "Resize",
  "Activity",
] as const;

// Customer-facing label overrides. The internal tab key stays "resize" so the
// ?tab=resize deep-links, the panels map and every internal reference keep
// working untouched — only the text the customer reads changes to "Upgrade".
const TAB_LABELS: Record<string, string> = {
  resize: "Upgrade",
};

export function ServerTabs({
  initialTab,
  overview,
  manage,
  mods,
  controlPanel,
  metrics,
  console: consolePanel,
  files,
  snapshots,
  backups,
  networking,
  resize,
  activity,
}: {
  initialTab?: string;
  overview: ReactNode;
  /** Game control panel — present (and shown as "Manage") for game servers only. */
  manage?: ReactNode;
  /** Mod/plugin manager — present ("Mods") for game servers only. */
  mods?: ReactNode;
  controlPanel: ReactNode;
  metrics: ReactNode;
  console: ReactNode;
  files: ReactNode;
  snapshots: ReactNode;
  backups: ReactNode;
  networking: ReactNode;
  resize: ReactNode;
  activity: ReactNode;
}) {
  // Game-only tabs are injected right after Overview, in order.
  const extra: string[] = [];
  if (manage) extra.push("Manage");
  if (mods) extra.push("Mods");
  const TABS: readonly string[] = extra.length ? ["Overview", ...extra, ...BASE_TABS.slice(1)] : BASE_TABS;
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
  );

  const panels: Record<string, ReactNode> = {
    overview,
    manage,
    mods,
    "control panel": controlPanel,
    metrics,
    console: consolePanel,
    files,
    snapshots,
    backups,
    networking,
    resize,
    activity,
  };

  return (
    <div>
      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
        {TABS.map((t) => {
          const k = t.toLowerCase();
          const active = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => {
                setTab(k);
                window.history.replaceState(null, "", `?tab=${k}`);
              }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {TAB_LABELS[k] ?? t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}

import type { HTMLAttributes, ReactNode } from "react";
import { IconArrowUp } from "./icons";

/**
 * Shared surface/card/badge/gauge primitives for the portal v2 redesign.
 * These are genuinely new components — NOT the existing components/ui/
 * primitives.tsx (PageHeader/StatCard/Badge/EmptyState) restyled in place.
 * That file stays untouched and keeps serving the ~54 pages not yet
 * redesigned; this one is additive, for pages built against the new visual
 * system (scratchpad/portal-redesign-{shell,wizard,billing,server}.html).
 *
 * Dependency-free by design, matching this codebase's existing discipline
 * (ROADMAP.md: "dependency-free charts", no chart library) — <Gauge> and
 * <BarMeter> are hand-rolled SVG/CSS, same philosophy as
 * components/ui/charts.tsx's <Sparkline>/<AreaChart>. Reuse that existing
 * <Sparkline> as-is for line/area trends on redesigned pages — it has no
 * dependency on the old `.card` system, so there's nothing to port.
 */

type Tone = "violet" | "cyan" | "green" | "blue";
type PillTone = "brand" | "good" | "warn" | "bad" | "neutral";

/* ── Surface ──────────────────────────────────────────────────────────── */

/**
 * Base panel/card surface (portal v2's answer to the old `.card`). Wraps the
 * `.pv-surface` / `.pv-surface-elevated` utility classes from globals.css so
 * plain markup and this component always stay pixel-identical.
 */
export function Surface({
  elevated = false,
  className = "",
  children,
  ...rest
}: HTMLAttributes<HTMLDivElement> & { elevated?: boolean }) {
  return (
    <div className={`${elevated ? "pv-surface-elevated" : "pv-surface"} ${className}`} {...rest}>
      {children}
    </div>
  );
}

/* ── IconTile ─────────────────────────────────────────────────────────── */

const ICON_TILE_TONES: Record<Tone, string> = {
  violet: "bg-pv-brand/[0.16] text-pv-brand-light",
  cyan: "bg-pv-cyan/[0.14] text-pv-cyan",
  green: "bg-pv-good/[0.14] text-pv-good",
  blue: "bg-pv-blue/[0.14] text-pv-blue",
};

/** The colored icon square behind every stat-card icon (shell mockup's `.stat-icon`). */
export function IconTile({
  tone = "violet",
  size = 34,
  children,
}: {
  tone?: Tone;
  size?: number;
  children: ReactNode;
}) {
  return (
    <div
      className={`flex shrink-0 items-center justify-center rounded-pv-sm ${ICON_TILE_TONES[tone]}`}
      style={{ width: size, height: size }}
    >
      {children}
    </div>
  );
}

/* ── Pill / StatusPill ────────────────────────────────────────────────── */

const PILL_TONES: Record<PillTone, string> = {
  brand: "bg-pv-brand/20 text-pv-brand-light",
  good: "bg-pv-good/[0.15] text-pv-good",
  warn: "bg-pv-warn/[0.15] text-pv-warn",
  bad: "bg-pv-bad/[0.15] text-pv-bad",
  neutral: "bg-white/[0.08] text-pv-text-muted",
};

/** Small static label pill — nav "NEW" tag, plan "Most popular" badge, term
 *  "Save 20%" callout. Not interactive; for a clickable variant, wrap it. */
export function Pill({ tone = "brand", children }: { tone?: PillTone; children: ReactNode }) {
  return (
    <span
      className={`inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-bold tracking-wide ${PILL_TONES[tone]}`}
    >
      {children}
    </span>
  );
}

const STATUS_DOT_TONES: Record<PillTone, string> = {
  brand: "bg-pv-brand-light shadow-[0_0_6px_#a48bff]",
  good: "bg-pv-good shadow-[0_0_6px_#34d399]",
  warn: "bg-pv-warn shadow-[0_0_6px_#fbbf24]",
  bad: "bg-pv-bad shadow-[0_0_6px_#f87171]",
  neutral: "bg-pv-text-faint",
};

/**
 * Status-dot-with-label pill (server-detail mockup's "● Running" chip). Unlike
 * components/ui/primitives.tsx's `StatusDot` (which maps raw enum status
 * strings like "RUNNING"/"SUSPENDED" to a color), this one takes an explicit
 * tone + label — the redesigned pages decide the mapping themselves, since
 * the new visual language uses a filled pill (not a bare dot + text).
 */
export function StatusPill({ tone = "good", children }: { tone?: PillTone; children: ReactNode }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold ${PILL_TONES[tone]}`}
    >
      <span className={`h-1.5 w-1.5 shrink-0 rounded-full ${STATUS_DOT_TONES[tone]}`} />
      {children}
    </span>
  );
}

/* ── StatCard ─────────────────────────────────────────────────────────── */

export interface StatCardV2Props {
  label: string;
  value: ReactNode;
  icon?: ReactNode;
  tone?: Tone;
  /** Omit for no trend indicator (matches the shell mockup's "Uptime" stat, which has none). */
  trend?: { direction: "up" | "down"; label: string };
  className?: string;
}

/** Portal v2 stat tile (shell mockup's `.stat-card`): icon tile + optional
 *  trend chip on top, big value, faint label below. */
export function StatCardV2({ label, value, icon, tone = "violet", trend, className = "" }: StatCardV2Props) {
  return (
    <Surface className={`p-[18px] ${className}`}>
      <div className="mb-3.5 flex items-center justify-between">
        {icon ? <IconTile tone={tone}>{icon}</IconTile> : <span />}
        {trend && (
          <span
            className={`flex items-center gap-0.5 text-[11px] font-bold ${
              trend.direction === "up" ? "text-pv-good" : "text-pv-bad"
            }`}
          >
            {trend.label}
            <IconArrowUp width={10} height={10} className={trend.direction === "down" ? "rotate-180" : ""} />
          </span>
        )}
      </div>
      <p className="mb-1 font-pv-display text-2xl font-bold leading-none text-pv-text">{value}</p>
      <p className="text-xs text-pv-text-faint">{label}</p>
    </Surface>
  );
}

/* ── Gauge (semicircular, billing mockup) ────────────────────────────── */

/**
 * Hand-rolled semicircular gauge — billing mockup's wallet-usage arc.
 * Geometry matches the mockup exactly: a 140x90 viewBox, radius-60 arc from
 * (10,80) to (130,80). That arc's true length is `π * r ≈ 188.5`, which is
 * where the mockup's hardcoded `stroke-dasharray="188"` came from — computed
 * here instead of hardcoded so `value` can be any 0-100, not just the
 * mockup's fixed 75%.
 */
export function Gauge({ value, size = 140 }: { value: number; size?: number }) {
  const pct = Math.max(0, Math.min(100, value));
  const height = size * (90 / 140);
  const arcLength = Math.PI * 60;
  const offset = arcLength * (1 - pct / 100);
  const gradientId = "pv-gauge-grad";
  return (
    <svg width={size} height={height} viewBox="0 0 140 90">
      <path d="M10 80 A60 60 0 0 1 130 80" fill="none" stroke="rgb(255 255 255 / 0.08)" strokeWidth="10" strokeLinecap="round" />
      <path
        d="M10 80 A60 60 0 0 1 130 80"
        fill="none"
        stroke={`url(#${gradientId})`}
        strokeWidth="10"
        strokeLinecap="round"
        strokeDasharray={arcLength}
        strokeDashoffset={offset}
        style={{ transition: "stroke-dashoffset 0.6s cubic-bezier(0.22,1,0.36,1)" }}
      />
      <defs>
        <linearGradient id={gradientId} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor="#a48bff" />
          <stop offset="100%" stopColor="#22d3ee" />
        </linearGradient>
      </defs>
      <text
        x="70"
        y="72"
        textAnchor="middle"
        fill="#f4f5fb"
        fontFamily="var(--font-pv-display)"
        fontWeight={700}
        fontSize="18"
      >
        {Math.round(pct)}%
      </text>
    </svg>
  );
}

/* ── BarMeter (linear, server-detail mockup) ─────────────────────────── */

/**
 * Linear usage bar — server-detail mockup's CPU/Memory/Disk meters.
 * `tone="warn"` reproduces the mockup's disk-at-76%-amber-to-red treatment;
 * use it once a metric crosses whatever threshold the calling page defines
 * (the mockup didn't encode a fixed rule — it's a per-page call).
 */
export function BarMeter({
  value,
  max = 100,
  tone = "brand",
}: {
  value: number;
  max?: number;
  tone?: "brand" | "warn";
}) {
  const pct = Math.max(0, Math.min(100, (value / max) * 100));
  return (
    <div className="h-1.5 overflow-hidden rounded-full bg-white/[0.06]">
      <div
        className="h-full rounded-full"
        style={{
          width: `${pct}%`,
          background:
            tone === "warn"
              ? "linear-gradient(90deg, #fbbf24, #f87171)"
              : "linear-gradient(90deg, #a48bff, #22d3ee)",
          transition: "width 0.5s cubic-bezier(0.22,1,0.36,1)",
        }}
      />
    </div>
  );
}

