/* ------------------------------------------------------------------ *
 * serverAction reports failures the customer can act on, not silence
 *
 * It was called bare inside startTransition, so a THROWN error reached the
 * browser as Next's redacted generic page (the specific "Delete your data
 * volume(s) before reinstalling" message lost), and `if (pending > 0) return;`
 * was a SILENT no-op — click Start, nothing happens, ever, no explanation.
 * ------------------------------------------------------------------ */

test("serverAction returns errors for the customer instead of throwing them away", () => {
  const src = stripCommentsAndStrings(readFileSync(new URL("../lib/actions.ts", import.meta.url), "utf8"));
  const body = /export async function serverAction[\s\S]*?\n\}/.exec(src)?.[0] ?? "";
  assert.ok(body, "found serverAction");
  // The reinstall-wipes-volumes guard now RETURNS its message (renderable) rather
  // than throwing it (redacted by Next).
  assert.ok(!/throw new Error\(\s*$/m.test(body) || /return \{[\s\S]*?error:/.test(body), "customer-facing failures return, not throw");
  assert.match(body, /return \{[\s\S]*?error:/, "at least one branch returns an actionable error");
  // The debounce is no longer a bare `return;`.
  assert.ok(
    !/if \(pending > 0\) return;/.test(body),
    "the one-job-at-a-time guard must explain itself, not silently swallow the click",
  );
  assert.match(body, /pending > 0\) return \{ error:/, "it now tells the customer another operation is running");
});

test("both serverAction call sites surface the returned error", () => {
  const customer = stripCommentsAndStrings(readFileSync(new URL("../components/ServerControls.tsx", import.meta.url), "utf8"));
  assert.match(customer, /const res = await serverAction\(/, "the customer control awaits the result");
  assert.match(customer, /if \(res\?\.error\) setError/, "and shows the error");
  const admin = stripCommentsAndStrings(readFileSync(new URL("../components/admin/ServerAdminActions.tsx", import.meta.url), "utf8"));
  assert.match(admin, /const res = await serverAction\(/, "the admin control awaits it too");
  assert.match(admin, /res\?\.error/, "and surfaces it");
});

