"use client";

import { useState, type ComponentType, type ReactNode } from "react";
import {
  IconOverview,
  IconLock,
  IconChart,
  IconMatrix,
  IconStack,
  IconGear,
  IconAlert,
} from "@/components/portal-v2/icons";

/**
 * Plain-VPS server-detail tabs, regrouped by TASK rather than 1:1 with each
 * underlying component — portal-v2 redesign
 * (scratchpad/portal-redesign-server.html): Access / Performance / Data
 * protection / Danger zone, plus Overview and Settings (Networking +
 * plan/storage changes). "Control panel" (the existing cPanel-style
 * websites/databases/apps manager) stays its own tab — it's substantial real
 * functionality with no clean home in the four task buckets. The game-server
 * panel (components/customer/gamepanel/GameServerPanel.tsx) has its own,
 * separate tab shell entirely — this component is the plain-VPS path only,
 * so there is no "Manage"/"Mods" game-only tab injection here any more.
 */
const TABS: { key: string; label: string; icon: ComponentType<{ width?: number; height?: number }> }[] = [
  { key: "overview", label: "Overview", icon: IconOverview },
  { key: "access", label: "Access", icon: IconLock },
  { key: "performance", label: "Performance", icon: IconChart },
  { key: "controlpanel", label: "Control panel", icon: IconMatrix },
  { key: "data", label: "Data protection", icon: IconStack },
  { key: "settings", label: "Settings", icon: IconGear },
  { key: "danger", label: "Danger zone", icon: IconAlert },
];

// Tab keys this page used before the task-based regroup (Metrics, Console,
// Files, Snapshots, Backups, Networking, Resize, Activity, "Control panel"
// with a space) — kept so a saved/bookmarked `?tab=` deep link still lands on
// the tab that now holds that content, instead of silently falling back to
// Overview.
const LEGACY_TAB_MAP: Record<string, string> = {
  metrics: "performance",
  console: "access",
  files: "access",
  snapshots: "data",
  backups: "data",
  networking: "settings",
  resize: "settings",
  activity: "overview",
  "control panel": "controlpanel",
};

export function ServerTabs({
  initialTab,
  overview,
  access,
  performance,
  controlPanel,
  dataProtection,
  settings,
  danger,
}: {
  initialTab?: string;
  overview: ReactNode;
  access: ReactNode;
  performance: ReactNode;
  controlPanel: ReactNode;
  dataProtection: ReactNode;
  settings: ReactNode;
  danger: ReactNode;
}) {
  const keys = TABS.map((t) => t.key);
  const resolvedInitial = initialTab
    ? LEGACY_TAB_MAP[initialTab.toLowerCase()] ?? initialTab.toLowerCase()
    : "overview";
  const [tab, setTab] = useState<string>(keys.includes(resolvedInitial) ? resolvedInitial : "overview");

  const panels: Record<string, ReactNode> = {
    overview,
    access,
    performance,
    controlpanel: controlPanel,
    data: dataProtection,
    settings,
    danger,
  };

  return (
    <div>
      <div className="mb-5 flex gap-1 overflow-x-auto border-b border-white/[0.07]">
        {TABS.map(({ key, label, icon: Icon }) => {
          const active = tab === key;
          return (
            <button
              key={key}
              type="button"
              onClick={() => {
                setTab(key);
                window.history.replaceState(null, "", `?tab=${key}`);
              }}
              className={`-mb-px flex items-center gap-1.5 whitespace-nowrap border-b-2 px-3.5 py-2.5 text-[13px] font-semibold transition-colors ${
                active
                  ? "border-pv-brand-light text-pv-text"
                  : "border-transparent text-pv-text-faint hover:text-pv-text-muted"
              }`}
            >
              <Icon width={15} height={15} />
              {label}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}

