/* ---------- Danger zone tab ----------
 * Every destructive/irreversible action on this server, gathered in one
 * place and kept OUT of the always-visible status header — portal-v2
 * redesign's explicit "Danger zone" requirement. Nothing here is a new
 * action: ReinstallOs (pick a different OS) is the same component that used
 * to sit at the bottom of the Resize tab; ServerControls's "danger" variant
 * (reinstall-in-place + delete) is the same buttons that used to sit in the
 * page's inline header; CancelService already self-documented as
 * "Danger-zone control for self-serve cancellation" — it just wasn't
 * visually grouped as one before. */
const dangerZone = (
  <div className="space-y-6">
    <p className="text-xs text-slate-500">
      These actions are permanent and can destroy data. Take a backup or snapshot first if you&apos;re unsure.
    </p>

    {/* Image minimum-disk checks run against the EFFECTIVE disk (totalDiskGB):
        a server that bought extra storage really does have room for a larger
        image than its plan alone would allow. */}
    <ReinstallOs
      serverId={server.id}
      currentOsTemplateId={server.osTemplateId}
      currentOsName={server.osTemplate.name}
      planRamMB={server.plan.ramMB}
      planDiskGB={totalDiskGB}
      templates={osTemplates.map((t) => ({
        id: t.id,
        name: t.name,
        family: t.family,
        version: t.version,
        minRamMB: t.minRamMB,
        minDiskGB: t.minDiskGB,
      }))}
      disabled={busy || !steady}
    />

    {/* Same gating the old inline header used for this exact block: useless
        on a SUSPENDED/ERROR server (no working VM to control) or mid-transition. */}
    {server.status !== "SUSPENDED" && server.status !== "ERROR" && !transitional && (
      <div className="card border-red-500/25 bg-red-500/[0.04]">
        <h2 className="mb-1 font-semibold text-red-300">Reinstall or delete this server</h2>
        <p className="mb-4 text-xs text-slate-500">
          Reinstall wipes the current OS in place and redeploys it fresh. Delete permanently removes the server and all its data.
        </p>
        <ServerControls serverId={server.id} status={server.status} busy={busy} variant="danger" />
      </div>
    )}

    {!server.isFree && server.status !== "DELETING" && (
      <CancelService
        serverId={server.id}
        hostname={server.hostname}
        expiresAt={server.expiresAt ? server.expiresAt.toISOString() : null}
        autoRenew={server.autoRenew}
        refundEstimateCents={terminationRefundCents({
          isFree: server.isFree,
          expiresAt: server.expiresAt,
          isGame: !!server.gamePlanId,
          planMonthlyCents: server.plan.priceCents,
          termMonths: server.termMonths,
          termPromoPercent: server.termPromoPercent,
          refundableTermCents: server.refundableTermCents,
          annualDiscountPct: frozenAnnualDiscountPct(server) ?? annualPct,
        })}
      />
    )}
  </div>
);

