return (
  <div>
    {overlay}
    {busy && <AutoRefresh />}

    <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
      <div>
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="page-title">{server.label || server.name}</h1>
          <StatusDot status={server.status} />
          <ServerRename serverId={server.id} label={server.label} fallback={server.name} />
