// Same gate the old inline header used for its Start/Reboot/Stop/Reinstall/
// Delete block: useless on a SUSPENDED/ERROR server (no working VM to
// control) or mid-transition, when the overlay/banners already say so.
const showRoutineControls = server.status !== "SUSPENDED" && server.status !== "ERROR" && !transitional;

return (
  <div>
    {overlay}
    {busy && <AutoRefresh />}

    <ServerStatusHeader
      serverId={server.id}
      label={server.label}
      fallback={server.name}
      hostname={server.hostname}
      status={server.status}
      isFree={server.isFree}
      planLine={`${server.plan.name} · ${server.plan.cpuCores} vCPU / ${server.plan.ramMB / 1024}GB · ${server.osTemplate.name}`}
      ipLine={(dedicated ? server.dedicatedIp!.address : server.ipAddress) ?? null}
      busy={busy}
      showControls={showRoutineControls}
      showTerminal={server.status === "RUNNING"}
      terminalServers={terminalServers}
    />

    {/* Alert rail — always visible above the tabs regardless of which tab is
        active, matching the pattern already used for ProvisionErrorBanner /
        ResourceLimitAlert elsewhere in the codebase. Order: account-level
        (suspended) > provisioning failure > in-progress > resource pressure. */}
    {server.status === "SUSPENDED" && (
      <div className="card mb-4 border-red-500/30 text-sm text-red-300">
        This server has been suspended{server.suspendedNote ? `: ${server.suspendedNote}` : "."}{" "}
        Contact support if you believe this is a mistake.
      </div>
    )}

    {server.status === "ERROR" && (
      <ProvisionErrorBanner serverId={server.id} reason={server.provisionError} />
    )}

    {transitional && (
      <div className="card mb-4 border-amber-500/30 text-sm text-amber-300">
        {server.status === "DELETING"
          ? "Your server is being deleted…"
          : "Your server is being set up — this usually takes under two minutes. The page refreshes automatically."}
      </div>
    )}

    {/* Wired from the same live stats fetched above for this render
        (`live.cpu`/`live.mem`/`live.maxmem`) — no new data fetching, same
        90% thresholds ResourceLimitAlert has always used. There's no
        per-page disk sample for a VPS (DiskUsageChart fetches its own
        client-side), so diskPct is simply omitted here, as before. */}
    {live && (
      <div className="mb-4">
        <ResourceLimitAlert
          cpuPct={(live.cpu ?? 0) * 100}
          memPct={live.maxmem ? ((live.mem ?? 0) / live.maxmem) * 100 : null}
          upgradeHref={`/dashboard/servers/${server.id}?tab=settings`}
        />
      </div>
    )}

    <ServerTabs
      initialTab={tab}
      overview={overview}
      access={accessTab}
      performance={performanceTab}
      controlPanel={<ControlPanel serverId={server.id} running={server.status === "RUNNING"} />}
      dataProtection={dataProtectionTab}
      settings={settingsTab}
      danger={dangerZone}
    />
  </div>
);

