66	/**
67	 * Pick the port forward that actually serves a game server's own port, not
68	 * just the first one on the record — a customer can add extra forwards
69	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
70	 * mistaken for the game's real connect port. Falls back to the first forward
71	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
72	 * exact-matching forward yet) still shows *something* rather than nothing.
73	 * Single shared helper so the provisioning-overlay connect string, the header
74	 * connect string, and the custom-domain DNS instructions can never drift from
75	 * each other the way three independent inline copies previously could.
76	 */
77	function gameForwardFor(server: {
78	  portForwards: { guestPort: number; publicPort: number }[];
79	  osTemplate: { family?: string | null };
80	  gamePlan?: { gameFamily?: string | null } | null;
81	}): { guestPort: number; publicPort: number } | undefined {
82	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
83	  const expectedPort = family ? GAME_PORT[family]?.port : undefined;
84	  return server.portForwards.find((f) => f.guestPort === expectedPort) ?? server.portForwards[0];
85	}
