87	function fmtUptime(seconds: number): string {
88	  if (!seconds || seconds <= 0) return "—";
89	  const d = Math.floor(seconds / 86400);
90	  const h = Math.floor((seconds % 86400) / 3600);
91	  const m = Math.floor((seconds % 3600) / 60);
92	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
93	}
